UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "Account": "WITH RECURSIVE profile (iaccountid, tdate, val) AS (SELECT pv.iaccountid, pv.tdate, json_parse(pv.val || format(''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\",\\"Last Update\\":\\"%s\\"}'', v.vcexternalaccountid, v.vcaccountname, pv.last_updated)) AS val FROM t17landingtest.profiles.account pv LEFT JOIN t17landingtest.masters.accounts v ON v.iaccountid = pv.iaccountid AND v.itenantid = :tenantid WHERE pv.tdate BETWEEN cast(:StartDate as TIMESTAMP) AND cast(:EndDate as TIMESTAMP) - INTERVAL ''1'' DAY AND v.vcexternalaccountid = :VpaAddress), flat (iaccountid, tdate, key, value) AS (SELECT iaccountid, tdate, key, value FROM profile, UNNEST(CAST(map_keys(CAST(json_extract(val, ''$'') AS MAP<VARCHAR, JSON>)) AS ARRAY<VARCHAR>), CAST(map_values(CAST(json_extract(val, ''$'') AS MAP<VARCHAR, JSON>)) AS ARRAY<JSON>)) AS t(key, value) UNION ALL SELECT f.iaccountid, f.tdate, f.key || ''.'' || j.key, j.value FROM flat f, UNNEST(CAST(map_keys(CAST(json_extract(f.value, ''$'') AS MAP<VARCHAR, JSON>)) AS ARRAY<VARCHAR>), CAST(map_values(CAST(json_extract(f.value, ''$'') AS MAP<VARCHAR, JSON>)) AS ARRAY<JSON>)) AS j(key, value) WHERE typeof(f.value) = ''json'') SELECT CAST(json_format(json_parse(''['' || array_join(array_agg(json_format(CAST(data AS JSON))), '','') || '']'')) AS VARCHAR) FROM (SELECT f.iaccountid, f.tdate, map_agg(COALESCE(m.vccolumnname, f.key), f.value) AS data FROM flat f LEFT JOIN t17landingtest.profiles.metadata m ON m.vcpath = f.key AND m.vcroot = ''account'' AND m.itenantid = :tenantid WHERE typeof(f.value) <> ''json'' GROUP BY f.iaccountid, f.tdate) a LIMIT 1000",
    "VPA": "WITH RECURSIVE profile (ivpaid, tdate, val) AS (SELECT pv.ivpaid, pv.tdate, json_parse(pv.val || format(''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\",\\"Last Update\\":\\"%s\\"}'', v.vcexternaladdressid, v.vcvpaname, pv.last_updated)) AS val FROM t17landingtest.profiles.vpa pv LEFT JOIN t17landingtest.masters.vpa v ON v.ivpaid = pv.ivpaid and v.itenantid=:tenantid WHERE pv.tdate BETWEEN cast(:StartDate as TIMESTAMP) AND cast(:EndDate as TIMESTAMP) - INTERVAL ''1'' DAY AND v.vcexternaladdressid = :VpaAddress), flat (ivpaid, tdate, key, value) AS (SELECT ivpaid, tdate, key, value FROM profile, UNNEST(CAST(map_keys(CAST(json_extract(val, ''$'') AS MAP<VARCHAR, JSON>)) AS ARRAY<VARCHAR>), CAST(map_values(CAST(json_extract(val, ''$'') AS MAP<VARCHAR, JSON>)) AS ARRAY<JSON>)) AS t(key, value) UNION ALL SELECT f.ivpaid, f.tdate, f.key || ''.'' || j.key, j.value FROM flat f, UNNEST(CAST(map_keys(CAST(json_extract(f.value, ''$'') AS MAP<VARCHAR, JSON>)) AS ARRAY<VARCHAR>), CAST(map_values(CAST(json_extract(f.value, ''$'') AS MAP<VARCHAR, JSON>)) AS ARRAY<JSON>)) AS j(key, value) WHERE typeof(f.value) = ''json'') SELECT CAST(json_format(json_parse(''['' || array_join(array_agg(json_format(CAST(data AS JSON))), '','') || '']'')) AS VARCHAR) FROM (SELECT f.ivpaid, f.tdate, map_agg(COALESCE(m.vccolumnname, f.key), f.value) AS data FROM flat f LEFT JOIN t17landingtest.profiles.metadata m ON m.vcpath = f.key AND m.vcroot = ''vpa'' AND m.itenantid = :tenantid WHERE typeof(f.value) <> ''json'' GROUP BY f.ivpaid, f.tdate) a LIMIT 1000"
}'::text WHERE
idashboardqueryid = 163 AND itenantid = 17;
